function jsonReadableContent(body,value){
 const labels={title:'标题',name:'名称',file:'文件',mp4:'MP4 文件',description:'说明',status:'状态',url:'资源链接',page:'来源页面',license:'使用说明',context:'原始上下文',bytes:'文件字节数',metadata:'文件信息'};
 function fields(host,obj){if(obj===null||typeof obj!=='object'){const p=document.createElement('p');p.textContent=typeof obj==='string'?obj:JSON.stringify(obj);host.append(p);return}for(const [key,val] of Object.entries(obj)){if(val!==null&&typeof val==='object'){host.append(jsonBranch(labels[key]||key,val));continue}const row=document.createElement('div');row.className='json-readable-field';const label=document.createElement('b');label.textContent=labels[key]?labels[key]+' · '+key:key;const text=document.createElement('div');if(typeof val==='string'&&/^https?:\/\/[^\s]+$/i.test(val)){const a=document.createElement('a');a.href=val;a.target='_blank';a.rel='noopener noreferrer';a.textContent=val;text.append(a)}else text.textContent=typeof val==='string'?val:JSON.stringify(val);row.append(label,text);host.append(row)}}
 if(!Array.isArray(value)){fields(body,value);if(value&&typeof value==='object'&&!Object.keys(value).length)body.textContent='空对象：没有字段';return}
 const count=document.createElement('p');count.className='json-notice';count.textContent='共 '+value.length+' 条记录';body.append(count);let offset=0;const more=document.createElement('button');more.textContent='继续显示后面的记录';more.type='button';const add=()=>{more.remove();for(const entry of value.slice(offset,offset+20)){const section=document.createElement('section');section.className='json-readable-record';const title=document.createElement('h4');title.textContent=(offset+1)+'. '+(entry&&typeof entry==='object'?[entry.title,entry.name,entry.file,entry.mp4].find(v=>typeof v==='string'&&v)||'记录':'记录');section.append(title);fields(section,entry);body.append(section);offset++}if(offset<value.length)body.append(more)};more.onclick=add;add();
}

function jsonBranch(key,value){if(value===null||typeof value!=='object'){const line=document.createElement('div');line.className='json-leaf';const name=document.createElement('b'),val=document.createElement('span');name.textContent=key+': ';val.textContent=JSON.stringify(value);line.append(name,val);return line}const details=document.createElement('details'),summary=document.createElement('summary'),children=document.createElement('div'),keys=Object.keys(value);summary.textContent=key+' '+(Array.isArray(value)?'['+keys.length+' 项]':'{'+keys.length+' 个字段}');details.append(summary,children);let loaded=false,index=0;const more=document.createElement('button');more.textContent='继续显示100项';const chunk=()=>{more.remove();keys.slice(index,index+100).forEach(k=>children.append(jsonBranch(k,value[k])));index+=100;if(index<keys.length)children.append(more)};more.onclick=chunk;details.ontoggle=()=>{if(details.open&&!loaded){loaded=true;chunk()}};return details}
