document.addEventListener('selectstart',e=>{if(document.body.classList.contains('canvas-gesture'))e.preventDefault()},true);

// Folder browser shared by creation and collection; values remain normal library paths.
function mountLibraryDestination(id){const select=$(id);if(!select||select.dataset.browserReady)return;select.dataset.browserReady='true';let current=select.value;const label=select.closest('label'),host=document.createElement('section');host.className='destination-picker';host.innerHTML='<span class="destination-label">存放位置</span><button type="button" class="destination-toggle" aria-expanded="false"><span class="destination-icon">▰</span><span class="destination-current"></span><span class="destination-change">更改…</span></button><div class="destination-browser" hidden><nav class="destination-crumbs" aria-label="存放位置路径"></nav><div class="destination-tools"><button type="button" class="destination-up">↑ 上一级</button><input class="destination-search" placeholder="搜索所有文件夹" aria-label="搜索存放文件夹"><button type="button" class="destination-new">新建文件夹</button></div><form class="destination-create" hidden><input aria-label="新文件夹名称" placeholder="文件夹名称" maxlength="120"><button type="submit">创建并进入</button><button type="button" class="destination-cancel">取消</button><p role="status"></p></form><div class="destination-list" role="group" aria-label="文件夹列表"></div><div class="destination-footer"><span></span><button type="button" class="destination-done">用这个位置</button></div></div>';
 label.replaceWith(host);select.hidden=true;host.append(select);const toggle=host.querySelector('.destination-toggle'),panel=host.querySelector('.destination-browser'),search=host.querySelector('.destination-search'),list=host.querySelector('.destination-list'),create=host.querySelector('.destination-create');
 const pathLabel=()=>current?'内容库 / '+current.split('/').join(' / '):'内容库根目录';
 const sync=()=>{if(![...select.options].some(o=>o.value===current))select.add(new Option(current||'内容库根目录',current));select.value=current;host.querySelector('.destination-current').textContent=pathLabel();host.querySelector('.destination-current').title=pathLabel();host.querySelector('.destination-footer span').textContent='将保存到：'+pathLabel()};
 const navigate=path=>{current=path;search.value='';create.hidden=true;draw()};
 const draw=()=>{sync();const crumbs=host.querySelector('.destination-crumbs');crumbs.replaceChildren();const addCrumb=(name,path)=>{const b=document.createElement('button');b.type='button';b.textContent=name;b.title=path||'内容库根目录';b.onclick=()=>navigate(path);crumbs.append(b)};addCrumb('内容库','');let acc='';for(const segment of current.split('/').filter(Boolean)){acc=acc?acc+'/'+segment:segment;crumbs.append(document.createTextNode(' › '));addCrumb(segment,acc)}host.querySelector('.destination-up').disabled=!current;const q=search.value.trim().toLowerCase(),folders=allAssetFolders().sort((a,b)=>a.localeCompare(b,'zh-CN')).filter(f=>q?f.toLowerCase().includes(q):(f.includes('/')?f.slice(0,f.lastIndexOf('/')):'')===current);list.replaceChildren();if(!folders.length){const empty=document.createElement('p');empty.className='destination-empty';empty.textContent=q?'没有找到文件夹。可以换个词，或在当前位置新建。':'这里没有子文件夹。可以直接存放在这里，也可以新建文件夹。';list.append(empty)}for(const path of folders){const row=document.createElement('button');row.type='button';row.className='destination-folder';const icon=document.createElement('span'),text=document.createElement('span'),name=document.createElement('strong'),detail=document.createElement('small'),arrow=document.createElement('span');icon.className='destination-icon';icon.textContent='▰';name.textContent=path.split('/').at(-1);detail.textContent=q?'内容库 / '+path:allAssetFolders().filter(f=>f.startsWith(path+'/')&&!f.slice(path.length+1).includes('/')).length+' 个子文件夹';text.append(name,detail);arrow.textContent='›';row.append(icon,text,arrow);row.title='进入 '+path;row.onclick=()=>navigate(path);list.append(row)}};
 toggle.onclick=()=>{panel.hidden=!panel.hidden;toggle.setAttribute('aria-expanded',String(!panel.hidden));if(!panel.hidden)draw()};host.querySelector('.destination-up').onclick=()=>navigate(current.includes('/')?current.slice(0,current.lastIndexOf('/')):'');search.oninput=draw;host.querySelector('.destination-done').onclick=()=>{panel.hidden=true;toggle.setAttribute('aria-expanded','false');toggle.focus()};host.querySelector('.destination-new').onclick=()=>{create.hidden=false;create.querySelector('input').value='';create.querySelector('p').textContent='';create.querySelector('input').focus()};host.querySelector('.destination-cancel').onclick=()=>create.hidden=true;
 create.onsubmit=async e=>{e.preventDefault();const input=create.querySelector('input'),name=input.value.trim(),status=create.querySelector('p');if(!name||/[\\/]/.test(name)||name==='.'||name==='..'){status.textContent='请填写名称，不要包含斜杠。';return}const path=(current?current+'/':'')+name;if(allAssetFolders().includes(path)){status.textContent='这里已有同名文件夹。';return}const next=clone(assetIndex);next.folders.push(path);const submit=create.querySelector('[type=submit]');submit.disabled=true;try{if(await saveAssets(next))navigate(path);else status.textContent='未能创建，请重试。'}finally{submit.disabled=false}};
 host.addEventListener('keydown',e=>{if(e.altKey&&e.key==='ArrowUp'){e.preventDefault();e.stopPropagation();host.querySelector('.destination-up').click()}});draw()
}
const writeBeforeFolderBrowser=writeLibraryContent;writeLibraryContent=function(id=null){writeBeforeFolderBrowser(id);mountLibraryDestination('libraryDestination')};
const collectBeforeFolderBrowser=askCollectSelection;askCollectSelection=function(){collectBeforeFolderBrowser();mountLibraryDestination('collectDestination')};
collectDock.onclick=()=>askCollectSelection();

// Anchors follow visible card bounds; new links preserve explicitly chosen ports.
const connectorSides=['top','right','bottom','left'];
const connectorVectors={top:{x:0,y:-1},right:{x:1,y:0},bottom:{x:0,y:1},left:{x:-1,y:0}};
function connectorBounds(n){const el=[...$('nodes').children].find(e=>e.dataset.id===n.id);return {x:n.x,y:n.y,w:el?.offsetWidth||n.w,h:el?.offsetHeight||n.h}}
anchor=function(n,side){const b=connectorBounds(n);return side==='left'?{x:b.x,y:b.y+b.h/2}:side==='top'?{x:b.x+b.w/2,y:b.y}:side==='bottom'?{x:b.x+b.w/2,y:b.y+b.h}:{x:b.x+b.w,y:b.y+b.h/2}};
function naturalConnectorSides(a,b,from=null,to=null){let best=null;for(const sa of from?[from]:connectorSides)for(const sb of to?[to]:connectorSides){const p=anchor(a,sa),q=anchor(b,sb),dx=q.x-p.x,dy=q.y-p.y,len=Math.hypot(dx,dy),va=connectorVectors[sa],vb=connectorVectors[sb];const penalty=Math.max(0,-dx*va.x-dy*va.y)+Math.max(0,dx*vb.x+dy*vb.y),score=len+penalty*2;if(!best||score<best.score)best={from:sa,to:sb,score}}return best}
function connectorCurve(p,q,from,to){const va=connectorVectors[from],vb=connectorVectors[to],distance=Math.hypot(q.x-p.x,q.y-p.y),pull=Math.min(150,Math.max(24,distance*.42));const c1={x:p.x+va.x*pull,y:p.y+va.y*pull},c2={x:q.x+vb.x*pull,y:q.y+vb.y*pull};return {path:'M '+p.x+' '+p.y+' C '+c1.x+' '+c1.y+', '+c2.x+' '+c2.y+', '+q.x+' '+q.y,mid:{x:(p.x+3*c1.x+3*c2.x+q.x)/8,y:(p.y+3*c1.y+3*c2.y+q.y)/8}}}
function connectorTarget(point,sourceId){const radius=20/view().z;let best=null;for(const n of board.nodes){if(n.id===sourceId)continue;const b=connectorBounds(n),inside=point.x>=b.x&&point.x<=b.x+b.w&&point.y>=b.y&&point.y<=b.y+b.h;for(const side of connectorSides){const p=anchor(n,side),distance=Math.hypot(point.x-p.x,point.y-p.y);if(distance>radius&&!inside)continue;const score=distance+(n.type==='frame'?10000:0);if(!best||score<best.score)best={id:n.id,side,point:p,score}}}return best}
function clearConnectorHints(){document.querySelectorAll('.connector-target,.connector-snap').forEach(el=>el.classList.remove('connector-target','connector-snap'))}
drawEdges=function(){if(!board)return;let html='';for(const e of board.edges){const a=board.nodes.find(n=>n.id===e.from),b=board.nodes.find(n=>n.id===e.to);if(!a||!b)continue;const sides=naturalConnectorSides(a,b,e.portsExplicit?e.fromSide:null,e.portsExplicit?e.toSide:null),p=anchor(a,sides.from),q=anchor(b,sides.to),curve=connectorCurve(p,q,sides.from,sides.to);html+='<g data-edge="'+esc(e.id)+'" class="connector '+(edgeId===e.id?'selected':'')+'"><path class="connector-hit" d="'+curve.path+'"/><path class="connector-line" d="'+curve.path+'" marker-end="url(#connectorArrow)"/>'+(e.label?'<text x="'+curve.mid.x+'" y="'+(curve.mid.y-9)+'" text-anchor="middle">'+esc(e.label)+'</text>':'')+'</g>'}clearConnectorHints();if(gesture?.type==='link'){const g=gesture,source=board.nodes.find(n=>n.id===g.id),snap=connectorTarget(g.current,g.id),start=source?anchor(source,g.side):g.start;g.snap=snap;const endpoint=snap?.point||g.current,side=snap?.side||({left:'right',right:'left',top:'bottom',bottom:'top'}[g.side]);const curve=connectorCurve(start,endpoint,g.side,side);html+='<path class="connector-preview" d="'+curve.path+'"/>';if(snap){const node=[...$('nodes').children].find(n=>n.dataset.id===snap.id);node?.classList.add('connector-target');node?.querySelector('[data-port="'+snap.side+'"]').classList.add('connector-snap')}}$('edgePaths').innerHTML=html};
const connectorDefs=$('links').querySelector('defs');connectorDefs.insertAdjacentHTML('beforeend','<marker id="connectorArrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto" markerUnits="strokeWidth"><path d="M 2 1 L 9 5 L 2 9" fill="none" stroke="#7e8994" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></marker>');
const endBeforeConnectorSnap=endGesture;endGesture=function(e,cancel=false){if(gesture?.type!=='link')return endBeforeConnectorSnap(e,cancel);const g=gesture,target=!cancel?connectorTarget(worldPoint(e.clientX,e.clientY),g.id):null;gesture=null;document.body.classList.remove('canvas-gesture');$('selection').hidden=true;clearConnectorHints();if(target&&!board.edges.some(edge=>edge.from===g.id&&edge.to===target.id&&edge.fromSide===g.side&&edge.toSide===target.side)){undoPoint();board.edges.push({id:uid(),from:g.id,to:target.id,fromSide:g.side,toSide:target.side,portsExplicit:true,label:''});change()}render()};
if(board)drawEdges();

// One click selects a connector; naming is an explicit double-click action.
const editConnectorLabel=openEdge;
openEdge=function(id){if(!board?.edges.some(e=>e.id===id))return;edgeId=id;selected.clear();editorId=null;render();canvas.focus();toast('已选中连线 · Delete 删除 · 双击编辑说明')};
canvas.addEventListener('dblclick',e=>{const edge=e.target.closest('[data-edge]');if(!edge)return;e.preventDefault();e.stopImmediatePropagation();editConnectorLabel(edge.dataset.edge)},true);
canvas.addEventListener('contextmenu',e=>{const edge=e.target.closest('[data-edge]');if(!edge)return;if(contextDown&&Math.hypot(e.clientX-contextDown.x,e.clientY-contextDown.y)>5)return;edgeId=edge.dataset.edge;selected.clear();editorId=null;drawEdges();fileMenu(e,[['删除连线  Delete',()=>removeSelected()],['编辑说明',()=>editConnectorLabel(edge.dataset.edge)]])},true);
